    <Preview>Takeoff pricing</Preview>
    <Tailwind config={createEmailTailwindConfig(theme)}>
      <Body
        style={{
          backgroundColor: pageBackgroundColor,
          fontFamily: SinglePricing_fontFamily,
        }}
        className="m-0"
